$ cd ~/pobrane
$ curl -s -X POST http://httpbin/post -H "Content-Type: application/json" -d '{"nazwa": "monitor", "cena": 900}' | jq '{json, naglowek: .headers["Content-Type"]}'
{
  "json": {
    "cena": 900,
    "nazwa": "monitor"
  },
  "naglowek": "application/json"
}
$ curl -s http://httpbin/post -d @produkt.json -H "Content-Type: application/json" | jq .json
{
  "cena": 900,
  "nazwa": "monitor"
}
$ curl -s -X PUT http://httpbin/put -H "Content-Type: application/json" -d '{"cena": 950}' | jq .json
{
  "cena": 950
}
$ curl -s -X DELETE http://httpbin/delete -o /dev/null -w "%{http_code}\n"
200
$ curl -s -i http://httpbin/status/201 | head -n 3
HTTP/1.1 201 CREATED
Server: gunicorn/19.9.0
Date: Sun, 04 Oct 2026 15:16:18 GMT

$ curl -s http://httpbin/headers -H "X-Api-Key: tajny-klucz-123" -H "Accept-Language: pl" | jq .headers
{
  "Accept": "*/*",
  "Accept-Language": "pl",
  "Host": "httpbin",
  "User-Agent": "curl/8.5.0",
  "X-Api-Key": "tajny-klucz-123"
}
$ curl -s -u anna:haslo http://httpbin/basic-auth/anna/haslo
{
  "authenticated": true,
  "user": "anna"
}
$ curl -s -o /dev/null -w "%{http_code}\n" -u anna:zle http://httpbin/basic-auth/anna/haslo
401
$ curl -s -H "Authorization: Bearer abc.def.ghi" http://httpbin/bearer
{
  "authenticated": true,
  "token": "abc.def.ghi"
}
$ curl -s -G http://httpbin/get --data-urlencode "szukaj=laptop 15 cali" -d "strona=2" | jq '{args, url}'
{
  "args": {
    "strona": "2",
    "szukaj": "laptop 15 cali"
  },
  "url": "http://httpbin/get?szukaj=laptop+15+cali&strona=2"
}
$ curl -s -F "plik=@produkt.json" -F "opis=test" http://httpbin/post | jq '{files, form}'
{
  "files": {
    "plik": "{\"nazwa\": \"monitor\", \"cena\": 900}\n"
  },
  "form": {
    "opis": "test"
  }
}

$ curl -s http://httpbin/post -d '{"nazwa": "monitor"}' | jq '{json, form, typ: .headers["Content-Type"]}'
{
  "json": null,
  "form": {
    "{\"nazwa\": \"monitor\"}": ""
  },
  "typ": "application/x-www-form-urlencoded"
}
$ curl -s http://httpbin/post -H "Content-Type: application/json" -d "{"nazwa": "monitor"}" | jq .data
"{nazwa: monitor}"
